// Genuary #01 : Vertical or hoizontal lines only

#define PI acos(-1.)
#define rot(a) mat2(cos(a), sin(a), -sin(a), cos(a))

#define hash11(u) fract(sin(u)*3683.4)
#define hash21(u) fract(sin(dot(u, vec2(18.4, 23.5)))*1583.4)
#define time iTime*.0002

float line (vec2 uv, float s)
{ return abs(uv.x)-s; }

vec3 frame (vec2 uv)
{
    vec2 outid;
    vec2 id = floor(uv); 
    float n = hash21(id);
    float d= 0.;

    if(n < .33) 
    {
        vec2 nid = floor(uv/.25);  
        if (hash21(nid) > .5) uv *= rot(PI/2.);  
        uv = mod(uv, .25)-.125;
        outid = nid;

        float per = .05;
        uv.x = mod(uv.x, per)-per*.5;
        d = smoothstep(.01, .015, line(uv, .004));
    }
    else
    {       
        if (n > .5) uv *= rot(PI/2.); 
        uv = fract(uv)-.5;
        outid = id; 

        float per = .2;
        uv.x = mod(uv.x, per)-per*.5;
        d = smoothstep(.01, .015, line(uv, .01));
    }

    return vec3(outid, d);
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = (2.*fragCoord-iResolution.xy)/iResolution.y;

    uv*= 3.5;
    vec3 f = frame(uv);

    int randnumX = int(floor(hash11(time+f.x)*14.-7.));
    int randnumY = int(floor(hash11(time+f.y)*14.-7.));

    vec3 col = vec3(f);
    col = (int(f.x) == randnumX && int(f.y) < randnumY) ? 
            mix(vec3(.2, .99, .6), vec3(.99, .5, .8), f.z) : 
            vec3(f.z);

    // Output to screen
    fragColor = vec4(sqrt(col),1.0);
}
